{"file_path":"src/scanner.js","content":"/**
 * The scanner. It turns UTF-8 source text into tokens, tracking the line and
 * column of every code point, and stops at the first error it meets.
 */

export const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

// Longest first, so that `==` wins over `=`.
export const PUNCTUATION = [
  '==', '!=', '<=', '>=', '&&', '||', '->', '=>',
  '+', '-', '*', '/', '%', '=', '<', '>', '!',
  '(', ')', '{', '}', '[', ']', ',', ';', '.',
]

const TAB_WIDTH = 4

export function isLetter(ch) {
  if (ch === null || ch === undefined) return false
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')
}

export function isDecimalDigit(ch) {
  if (ch === null || ch === undefined) return false
  return ch >= '0' && ch <= '9'
}

export function isHexDigit(ch) {
  if (ch === null || ch === undefined) return false
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F')
}

export function isOctalDigit(ch) {
  if (ch === null || ch === undefined) return false
  return ch >= '0' && ch <= '7'
}

export function isBinaryDigit(ch) {
  return ch === '0' || ch === '1'
}

export class ScanError extends Error {
  constructor(line, column, reason) {
    super(`${line}:${column}: ${reason}`)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

export class Scanner {
  constructor(input) {
    // Positions count code points, not UTF-16 units.
    this.cp = Array.from(input)
    this.pos = 0
    this.line = 1
    this.column = 1
    this.tokens = []
  }

  peek(offset = 0) {
    const idx = this.pos + offset
    if (idx < 0 || idx >= this.cp.length) return null
    return this.cp[idx]
  }

  atEnd() {
    return this.pos >= this.cp.length
  }

  advance() {
    if (this.atEnd()) return null
    const ch = this.cp[this.pos]
    this.pos++
    if (ch === '\n') {
      this.line++
      this.column = 1
    } else if (ch === '\t') {
      this.column = Math.floor((this.column - 1) / TAB_WIDTH) * TAB_WIDTH + TAB_WIDTH + 1
    } else {
      this.column++
    }
    return ch
  }

  fail(line, column, reason) {
    throw new ScanError(line, column, reason)
  }

  mark() {
    return { line: this.line, column: this.column }
  }

  skipWhitespace() {
    while (!this.atEnd()) {
      const ch = this.peek()
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\n') this.advance()
      else break
    }
  }

  scanLineComment() {
    this.advance()
    this.advance()
    while (!this.atEnd() && this.peek() !== '\n') this.advance()
  }

  scanBlockComment() {
    const start = this.mark()
    this.advance()
    this.advance()
    let depth = 1
    while (!this.atEnd() && depth > 0) {
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
      } else if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
      } else {
        this.advance()
      }
    }
    if (depth > 0) this.fail(start.line, start.column, 'unterminated block comment')
  }

  scanEscape(open) {
    const slash = this.mark()
    this.advance() // the backslash
    const ch = this.peek()
    if (ch === null) this.fail(open.line, open.column, 'unterminated string')

    const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
    if (Object.prototype.hasOwnProperty.call(simple, ch)) {
      this.advance()
      return simple[ch]
    }

    if (ch === 'x') {
      this.advance()
      if (!isHexDigit(this.peek()) || !isHexDigit(this.peek(1))) {
        this.fail(slash.line, slash.column, 'invalid escape \\x')
      }
      const hex = this.advance() + this.advance()
      return String.fromCodePoint(parseInt(hex, 16))
    }

    if (ch === 'u') {
      this.advance()
      if (this.peek() !== '{') this.fail(slash.line, slash.column, 'invalid escape \\u')
      this.advance()
      let hex = ''
      while (isHexDigit(this.peek())) hex += this.advance()
      if (hex.length === 0 || this.peek() !== '}') {
        this.fail(slash.line, slash.column, 'invalid escape \\u')
      }
      const code = parseInt(hex, 16)
      if (!Number.isFinite(code) || code > 0x10ffff) {
        this.fail(slash.line, slash.column, 'invalid escape \\u')
      }
      this.advance() // the closing brace
      return String.fromCodePoint(code)
    }

    this.fail(slash.line, slash.column, `invalid escape \\${ch}`)
  }

  scanString() {
    const start = this.mark()
    this.advance() // the opening quote
    let value = ''
    while (!this.atEnd()) {
      const ch = this.peek()
      if (ch === '"') {
        this.advance()
        return { kind: 'string', value, line: start.line, column: start.column }
      }
      if (ch === '\n') this.fail(this.line, this.column, 'newline in string')
      if (ch === '\\') value += this.scanEscape(start)
      else value += this.advance()
    }
    this.fail(start.line, start.column, 'unterminated string')
  }

  scanRawString() {
    const start = this.mark()
    this.advance() // the r
    this.advance() // the opening quote
    let value = ''
    while (!this.atEnd()) {
      if (this.peek() === '"') {
        this.advance()
        return { kind: 'rawstring', value, line: start.line, column: start.column }
      }
      value += this.advance()
    }
    this.fail(start.line, start.column, 'unterminated string')
  }

  /**
   * Reads a run of digits accepted by `isDigit`, allowing `_` only between two
   * of them. It returns the text read and whether the run was well formed.
   */
  readDigitRun(isDigit) {
    let text = ''
    let ok = true
    while (!this.atEnd() && (isDigit(this.peek()) || this.peek() === '_')) {
      if (this.peek() === '_') {
        if (!isDigit(this.peek(-1)) || !isDigit(this.peek(1))) {
          text += this.advance()
          ok = false
          break
        }
      }
      text += this.advance()
    }
    return { text, ok }
  }

  scanNumber() {
    const start = this.mark()
    let text = ''
    let valid = true

    const prefixed = (isDigit) => {
      text += this.advance() // the 0
      text += this.advance() // the prefix letter
      if (!isDigit(this.peek())) {
        valid = false
        return
      }
      const run = this.readDigitRun(isDigit)
      text += run.text
      if (!run.ok) valid = false
    }

    const second = this.peek(1)
    if (this.peek() === '0' && (second === 'x' || second === 'X')) {
      prefixed(isHexDigit)
    } else if (this.peek() === '0' && (second === 'b' || second === 'B')) {
      prefixed(isBinaryDigit)
    } else if (this.peek() === '0' && (second === 'o' || second === 'O')) {
      prefixed(isOctalDigit)
    } else {
      const whole = this.readDigitRun(isDecimalDigit)
      text += whole.text
      if (!whole.ok) valid = false

      if (valid && this.peek() === '.' && isDecimalDigit(this.peek(1))) {
        text += this.advance()
        const frac = this.readDigitRun(isDecimalDigit)
        text += frac.text
        if (!frac.ok) valid = false
      }

      if (valid && (this.peek() === 'e' || this.peek() === 'E')) {
        const signed = this.peek(1) === '+' || this.peek(1) === '-'
        const afterSign = signed ? this.peek(2) : this.peek(1)
        if (isDecimalDigit(afterSign)) {
          text += this.advance() // the exponent marker
          if (signed) text += this.advance()
          const exp = this.readDigitRun(isDecimalDigit)
          text += exp.text
          if (!exp.ok) valid = false
        } else {
          // The marker does not continue the number, so it is a trailing letter.
          text += this.advance()
          if (signed) text += this.advance()
          valid = false
        }
      }
    }

    // A letter, a digit or `_` glued to the end of a number is an error.
    if (isLetter(this.peek()) || isDecimalDigit(this.peek()) || this.peek() === '_') {
      valid = false
      while (isLetter(this.peek()) || isDecimalDigit(this.peek()) || this.peek() === '_') {
        text += this.advance()
      }
    }

    if (!valid) this.fail(start.line, start.column, `invalid number ${text}`)
    return { kind: 'number', value: text, line: start.line, column: start.column }
  }

  scanIdentifier() {
    const start = this.mark()
    let text = ''
    while (isLetter(this.peek()) || isDecimalDigit(this.peek()) || this.peek() === '_') {
      text += this.advance()
    }
    return {
      kind: KEYWORDS.has(text) ? 'keyword' : 'ident',
      value: text,
      line: start.line,
      column: start.column,
    }
  }

  scanPunctuation() {
    const start = this.mark()
    for (const punct of PUNCTUATION) {
      let matches = true
      for (let i = 0; i < punct.length; i++) {
        if (this.peek(i) !== punct[i]) {
          matches = false
          break
        }
      }
      if (!matches) continue
      for (let i = 0; i < punct.length; i++) this.advance()
      return { kind: 'punct', value: punct, line: start.line, column: start.column }
    }
    return null
  }

  scan() {
    while (true) {
      this.skipWhitespace()
      if (this.atEnd()) break

      const ch = this.peek()
      const line = this.line
      const column = this.column

      if (ch === '/' && this.peek(1) === '/') {
        this.scanLineComment()
        continue
      }
      if (ch === '/' && this.peek(1) === '*') {
        this.scanBlockComment()
        continue
      }
      if (ch === '"') {
        this.tokens.push(this.scanString())
        continue
      }
      if (ch === 'r' && this.peek(1) === '"') {
        this.tokens.push(this.scanRawString())
        continue
      }
      if (isDecimalDigit(ch)) {
        this.tokens.push(this.scanNumber())
        continue
      }
      if (isLetter(ch) || ch === '_') {
        this.tokens.push(this.scanIdentifier())
        continue
      }
      const punct = this.scanPunctuation()
      if (punct) {
        this.tokens.push(punct)
        continue
      }
      this.fail(line, column, `unexpected character ${ch}`)
    }
    return this.tokens
  }
}

export function scan(input) {
  return new Scanner(input).scan()
}
