/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'

import { Scanner, ScanError } from './scanner.js'

const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function body(token) {
  if (token.kind === 'string' || token.kind === 'rawstring') return JSON.stringify(token.value)
  return token.value
}

function renderTokens(tokens) {
  let out = ''
  for (const token of tokens) {
    out += `${token.line}:${token.column} ${token.kind} ${body(token)}\n`
  }
  return out
}

function renderStats(tokens) {
  const counts = new Map(KINDS.map((kind) => [kind, 0]))
  for (const token of tokens) counts.set(token.kind, counts.get(token.kind) + 1)
  let out = ''
  for (const kind of KINDS) out += `${kind} ${counts.get(kind)}\n`
  out += `total ${tokens.length}\n`
  return out
}

function die(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
    die('usage: cli.js tokens|stats')
  }

  const input = readStdin()

  let tokens
  try {
    tokens = new Scanner(input).scan()
  } catch (err) {
    if (err instanceof ScanError) die(`${err.line}:${err.column}: ${err.reason}`)
